def generate(seed: int):
    rng = make_rng(FAMILY_ID, seed)
    org = rng.choice(ORGS)
    vals = dict(org=org, teams=rng.choice([12, 18, 25, 40]), qa=rng.choice([5, 7, 9]), releases=rng.choice([20, 40, 60, 100]), incidents=rng.choice([14, 22, 35]), escaped=rng.choice([40, 55, 65]), reg_days=rng.choice([3, 4, 5]), cov=rng.choice([85, 90, 95]), repos=rng.choice([60, 120, 200]), canary=rng.choice([1, 2, 5]), rollback=rng.choice([30, 45, 60]))
    return design_review_variant(
        FAMILY_ID, seed, rng, context=org, doc_title="Программа качества на два квартала",
        intro="Организация — {org}: {teams} продуктовых команд и {qa} инженеров по качеству; руководство просит программу качества, потому что дефекты всё чаще доходят до клиентов.".format(**vals), lines=LINES, issues=ISSUES, vals=vals,
        length="12–20 предложений", role="главный инженер по качеству (уровень Principal)",
        doc_kind="документа",
        priority_crit="Расставляет приоритет по влиянию на всю организацию (что остановит выкатки, что исказит поведение людей, что пропустит дефекты к клиентам) и предлагает поэтапный план перехода с критериями успеха и способом проверки",
        extra_notes="Уровень Principal: важно увидеть конфликт пунктов с ограничениями из контекста (число команд и инженеров, частота выкаток) и организационные последствия (стимулы, культура разборов), а не перечислить практики. Числа — из условия варианта.")
